{"python": "def pilot_policy(trace):
    import json as json
    from collections import set, list
    action, label = trace[-1]
    tool_name = action.name
    params = json.loads(action.arguments)
    categories = label.subset

    policy = {
        "slot:archive": {"UNVERIFIED"},
        "slot:counsel": {"UNVERIFIED"},
        "slot:public": {"PERSONAL", "EMBARGOED", "LICENSED"},
        "slot:syndicate": {"PERSONAL", "EMBARGOED"},
        "slot:wire": {"PERSONAL", "LICENSED"}
    }

    if tool_name == "research/collect_material":
        return None

    elif tool_name == "editor/edit_draft":
        return None

    elif tool_name == "publisher/review_release":
        return None

    elif tool_name in ("editorial/publish", "legal/publish"):
        audience = params.get("audience")
        source = params.get("source")
        assets = params.get("assets")
        record = params.get("record")

        target_slots = []
        if tool_name == "editorial/publish":
            audience_map = {"staff": "slot:newsroom", "partner": "slot:syndicate", "release": "slot:public"}
        else:
            audience_map = {"staff": "slot:newsroom", "partner": "slot:counsel", "release": "slot:wire"}

        main_slot = audience_map.get(audience)
        if main_slot:
            target_slots.append(main_slot)

        if record == "archive":
            target_slots.append("slot:archive")
        elif record == "partner":
            if tool_name == "editorial/publish":
                target_slots.append("slot:syndicate")
            else:
                target_slots.append("slot:counsel")
        elif record == "public":
            target_slots.append("slot:public")

        for slot in set(target_slots):
            allowed = policy.get(slot, set())
            if not categories.issubset(allowed):
                raise PolicyViolation(f"Categories {categories} not allowed in {slot}")

        return None

    else:
        raise PolicyViolation(f"Unknown tool: {tool_name}")"}
